#include PROTOCOL_HEADER
#include "frame_helpers.h"
int main(){CHECK(Proto::VERSION==5&&Proto::SAFETY_POLICY==23&&Proto::SENSOR_TELEMETRY==24);CHECK(Proto::AUX_AVAILABLE==32&&Proto::ADAS_ACTIVE_FLAG==64&&Proto::ADAS_BYPASS_FLAG==128);Proto::Frame q=policy(1,2,1);CHECK(Proto::len(q)==9&&Proto::valid(q)&&Proto::get32(Proto::payload(q))==100&&Proto::get32(Proto::payload(q)+4)==2&&Proto::payload(q)[8]==1);Proto::SensorTelemetry v;for(uint16_t mm:{uint16_t(20),uint16_t(100),uint16_t(199),uint16_t(200),uint16_t(250),uint16_t(4000)}){q=telemetry(1,2,1,mm,200,3);CHECK(Proto::decodeTelemetry(q,v)&&v.rangeMm==mm&&v.ageMs==200&&v.session==100&&v.epoch==2);}for(auto qbad:{telemetry(1,2,1,19,0,3),telemetry(1,2,1,4001,0,3),telemetry(1,2,1,250,201,3),telemetry(1,2,1,250,0,64),telemetry(1,2,1,250,0,3,2)})CHECK(!Proto::decodeTelemetry(qbad,v));q=telemetry(1,2,1,250,0,3);q.bytes[7]^=1;CHECK(!Proto::decodeTelemetry(q,v));Proto::SharedState s={100,3,2,1,1,1,5,0,0,true,128},decoded;CHECK(Proto::decodeState(sync(s),decoded)&&decoded.actorFlags==128&&!decoded.appliedFlags);CHECK(!Proto::supportedIntent(5)&&!Proto::supportedIntent(6)&&!Proto::supportedIntent(7));puts("PASS protocol5 wire values, range/age bounds, CRC, capabilities and unsupported intents");}
